settings.custom_liquid:
{% liquid
  assign item_count = cart.item_count
  assign max_tier = 4
  assign progress = item_count | times: 100 | divided_by: max_tier

  if progress > 100
    assign progress = 100
  endif

  if item_count >= 4
    assign current_discount = 20
  elsif item_count == 3
    assign current_discount = 15
  elsif item_count == 2
    assign current_discount = 10
  else
    assign current_discount = 0
  endif
%}

<div class="fs-wrapper" id="qty-discount-widget" data-item-count="{{ item_count }}">
  <div class="fs-widget">
    <div class="fs-message" data-fs-message>
      {% if item_count >= 4 %}
        <span class="emoji">🎉</span>
        <span>
          <strong>20% OFF unlocked!</strong>
          Your cart qualifies for the maximum discount.
        </span>

      {% elsif item_count == 3 %}
        <span class="emoji">✨</span>
        <span>
          <strong>15% OFF unlocked!</strong>
          Add <strong>1 more item</strong> to get <strong>20% off</strong>.
        </span>

      {% elsif item_count == 2 %}
        <span class="emoji">✨</span>
        <span>
          <strong>10% OFF unlocked!</strong>
          Add <strong>1 more item</strong> to get <strong>15% off</strong>.
        </span>

      {% elsif item_count == 1 %}
        <span class="emoji">✨</span>
        <span>
          Add <strong>1 more item</strong> to unlock <strong>10% off</strong>.
        </span>

      {% else %}
        <span class="emoji">🛍️</span>
        <span>
          Buy <strong>2 items</strong> for 10% off ·
          <strong>3</strong> for 15% ·
          <strong>4+</strong> for 20%.
        </span>
      {% endif %}
    </div>

    {% unless item_count >= 4 %}
      <div class="fs-progress" data-fs-progress-wrap>
        <div
          class="fs-progress-fill"
          data-fs-progress-fill
          style="width:{{ progress }}%;">
        </div>
      </div>

      <div class="fs-footer" data-fs-footer>
        <span data-fs-tier-note>
          {% if item_count == 0 %}
            2 items → 10% · 3 items → 15% · 4+ items → 20%
          {% elsif item_count == 1 %}
            Next: 2 items → 10% off
          {% elsif item_count == 2 %}
            Next: 3 items → 15% off
          {% elsif item_count == 3 %}
            Next: 4 items → 20% off
          {% endif %}
        </span>
        <a href="/collections/all">Continue shopping →</a>
      </div>
    {% endunless %}
  </div>
</div>

<style>
.fs-wrapper {
  padding: 0 16px;
  margin: 12px 0;
}

.fs-widget {
  max-width: 560px;
  margin: auto;
  background: #f7fcf8;
  border-radius: 10px;
  padding: 10px 14px;
}

.fs-message {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  line-height: 1.4;
  color: #1f2937;
}

.fs-message strong {
  font-weight: 700;
}

.emoji {
  font-size: 18px;
  flex-shrink: 0;
}

.fs-progress {
  margin-top: 8px;
  height: 4px;
  background: #dfe8e2;
  border-radius: 999px;
  overflow: hidden;
}

.fs-progress-fill {
  height: 100%;
  background: #22c55e;
  border-radius: 999px;
  transition: width .35s ease;
}

.fs-footer {
  margin-top: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.fs-footer span {
  font-size: 12px;
  color: #4b5563;
}

.fs-footer a {
  font-size: 12px;
  color: #15803d;
  text-decoration: none;
  font-weight: 600;
}

.fs-footer a:hover {
  text-decoration: underline;
}

@media (max-width: 768px) {
  .fs-wrapper {
    padding: 0;
  }

  .fs-widget {
    max-width: 100%;
    padding: 10px 12px;
  }

  .fs-message {
    font-size: 13px;
  }
}
</style>

<script>
  (function () {
    var root = document.getElementById('qty-discount-widget');
    if (!root) return;

    function getMessageHtml(count) {
      if (count >= 4) {
        return '<span class="emoji">🎉</span><span><strong>20% OFF unlocked!</strong> Your cart qualifies for the maximum discount.</span>';
      }
      if (count === 3) {
        return '<span class="emoji">✨</span><span><strong>15% OFF unlocked!</strong> Add <strong>1 more item</strong> to get <strong>20% off</strong>.</span>';
      }
      if (count === 2) {
        return '<span class="emoji">✨</span><span><strong>10% OFF unlocked!</strong> Add <strong>1 more item</strong> to get <strong>15% off</strong>.</span>';
      }
      if (count === 1) {
        return '<span class="emoji">✨</span><span>Add <strong>1 more item</strong> to unlock <strong>10% off</strong>.</span>';
      }
      return '<span class="emoji">🛍️</span><span>Buy <strong>2 items</strong> for 10% off · <strong>3</strong> for 15% · <strong>4+</strong> for 20%.</span>';
    }

    function getTierNote(count) {
      if (count <= 0) return '2 items → 10% · 3 items → 15% · 4+ items → 20%';
      if (count === 1) return 'Next: 2 items → 10% off';
      if (count === 2) return 'Next: 3 items → 15% off';
      if (count === 3) return 'Next: 4 items → 20% off';
      return '';
    }

    function render(count) {
      var message = root.querySelector('[data-fs-message]');
      var progressWrap = root.querySelector('[data-fs-progress-wrap]');
      var progressFill = root.querySelector('[data-fs-progress-fill]');
      var footer = root.querySelector('[data-fs-footer]');
      var tierNote = root.querySelector('[data-fs-tier-note]');
      var progress = Math.min(100, Math.round((count / 4) * 100));

      if (message) message.innerHTML = getMessageHtml(count);

      if (count >= 4) {
        if (progressWrap) progressWrap.style.display = 'none';
        if (footer) footer.style.display = 'none';
      } else {
        if (progressWrap) {
          progressWrap.style.display = '';
          if (progressFill) progressFill.style.width = progress + '%';
        }
        if (footer) {
          footer.style.display = '';
          if (tierNote) tierNote.textContent = getTierNote(count);
        }
      }

      root.setAttribute('data-item-count', String(count));
    }

    function refreshFromCart() {
      return fetch('/cart.js')
        .then(function (res) { return res.json(); })
        .then(function (cart) {
          render(cart.item_count || 0);
        })
        .catch(function () {});
    }

    // Cập nhật khi đổi quantity trên trang cart
    document.addEventListener('change', function (e) {
      if (!e.target) return;
      if (
        e.target.matches('input[name="updates[]"], input[name="quantity"], .quantity__input, [data-quantity-input]')
      ) {
        setTimeout(refreshFromCart, 250);
      }
    });

    document.addEventListener('click', function (e) {
      var btn = e.target.closest(
        'button[name="plus"], button[name="minus"], .quantity__button, [data-quantity-increment], [data-quantity-decrement], .qty-btn, cart-remove-button, [data-cart-remove]'
      );
      if (!btn) return;
      setTimeout(refreshFromCart, 250);
      setTimeout(refreshFromCart, 600);
    }, true);

    ['cart:updated', 'cart:change', 'cart:refresh', 'theme:cart:change'].forEach(function (evt) {
      document.addEventListener(evt, refreshFromCart);
    });

    var nativeFetch = window.fetch;
    window.fetch = function () {
      var url = arguments[0];
      var urlString = typeof url === 'string' ? url : (url && url.url ? url.url : '');
      return nativeFetch.apply(this, arguments).then(function (response) {
        if (/\/cart\/(add|change|update|clear)/.test(urlString)) {
          setTimeout(refreshFromCart, 150);
        }
        return response;
      });
    };
  })();
</script>
